import EditItem from "@/components/SettingsDialogs/EditItem.vue";
import DeleteItem from "@/components/SettingsDialogs/DeleteItem.vue";
import ViewItems from "@/components/SettingsDialogs/ViewItems.vue";
import SnackBar from "@/components/SnackBar.vue";
import { quotation_sub_categories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  components: {
    SnackBar,
    DeleteItem,
    EditItem,
    ViewItems
  },
  mixins: [get_all_org_users],
  data() {
    return {
      componentCheck: 0,
      SnackBarComponent: {},
      rowInfo: {},
      tableLoading: false,
      allUSersNames: [],
      itemdeletion: false,
      itemEdition: false,
      fixed: true,
      searchQuery: "",
      currentPage: 1,
      itemsPerPage: 10,
      sortBy: [{
        key: "sub_category_name",
        order: "asc"
      }],
      itemsRecords: [],
      categoriesHeaders: [{
        title: "Image",
        value: "sub_category_Image",
        sortable: false,
        align: "center",
        width: "80px"
      }, {
        title: "Product Name",
        value: "sub_category_name",
        sortable: true,
        align: "start"
      }, {
        title: "Type",
        value: "sub_category_type",
        sortable: true,
        align: "start"
      }, {
        title: "SKU Code",
        value: "sub_category_Sku",
        sortable: true,
        align: "start"
      }, {
        title: "Description",
        value: "sub_category_description",
        sortable: true,
        align: "start"
      }, {
        title: "Created By",
        value: "sub_category_created_by",
        sortable: true,
        align: "start"
      }, {
        title: "Actions",
        value: "actions",
        sortable: false,
        align: "center"
      }],
      windowHeight: 0,
      ViewProductDialog: false
    };
  },
  computed: {
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.itemsRecords;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.itemsRecords.filter(item => item.sub_category_name && item.sub_category_name.toLowerCase().includes(searchTerm) || item.sub_category_Sku && item.sub_category_Sku.toLowerCase().includes(searchTerm) || item.sub_category_type && item.sub_category_type.toLowerCase().includes(searchTerm) || item.sub_category_description && item.sub_category_description.toLowerCase().includes(searchTerm) || item.sub_category_created_by && this.fetch_user_name(item.sub_category_created_by).toLowerCase().includes(searchTerm));
    },
    sortedAndPaginatedItems() {
      // First sort the filtered items
      const sortedItems = this.filteredItems.slice().sort((a, b) => {
        for (const sort of this.sortBy) {
          const aValue = this.getSortValue(a[sort.key], sort.key);
          const bValue = this.getSortValue(b[sort.key], sort.key);
          if (aValue < bValue) return sort.order === "asc" ? -1 : 1;
          if (aValue > bValue) return sort.order === "asc" ? 1 : -1;
        }
        return 0;
      });

      // Then paginate
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    totalItems() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
    currentPage(newVal) {
      // When the page changes, scroll to top of the card container
      this.$nextTick(() => {
        const cardContainer = document.querySelector(".card-container");
        if (cardContainer) {
          cardContainer.scrollIntoView({
            behavior: "smooth",
            block: "start"
          });
        } else {
          // Fallback to scrolling to top of page
          window.scrollTo({
            top: 0,
            behavior: "smooth"
          });
        }
      });
    }
  },
  async mounted() {
    this.windowHeight = window.innerHeight - 380;
    await this.fetch_items();
    await this.get_all_org_users();
    this.allUSersNames = this.orgUsers;
  },
  methods: {
    add_items() {
      // This method should be implemented to add new items
    },
    getTypeColor(type) {
      const colors = {
        physical: "blue",
        digital: "green",
        service: "orange",
        default: "grey"
      };
      return colors[type?.toLowerCase()] || colors.default;
    },
    deletion(item) {
      this.rowInfo = item;
      this.componentCheck = 1;
      this.itemdeletion = true;
    },
    edition(item) {
      this.rowInfo = item;
      this.componentCheck = 2;
      this.itemEdition = true;
    },
    View_Product(item) {
      this.rowInfo = item;
      this.componentCheck = 3;
      this.ViewProductDialog = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    fetch_user_name(value) {
      var name = "";
      this.allUSersNames.forEach(element => {
        if (element.user_email_id == value) {
          name = element.full_user_name;
        }
      });
      if (value == "SYSTEM") {
        name = value;
      }
      return name;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.itemdeletion = false;
      this.itemEdition = false;
      this.ViewProductDialog = false;
      this.itemsRecords = [];
      this.fetch_items();
    },
    getSortValue(value, key) {
      if (!value) return "";
      if (key === "sub_category_name" || key === "sub_category_Sku" || key === "sub_category_type" || key === "sub_category_description" || key === "sub_category_created_by") {
        return value.toLowerCase();
      }
      return value;
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
      this.currentPage = 1; // Reset to first page when sorting changes
    },
    async fetch_items() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(quotation_sub_categories, {
          input: {
            action_type: "LIST"
          }
        }));
        var response = JSON.parse(result.data.quotation_sub_categories);
        this.itemsRecords = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          // Check multiple possible data structures
          let itemsData = null;
          if (response.data && Array.isArray(response.data)) {
            itemsData = response.data;
          } else if (response.items && Array.isArray(response.items)) {
            itemsData = response.items;
          } else if (response.result && Array.isArray(response.result)) {
            itemsData = response.result;
          } else if (response.products && Array.isArray(response.products)) {
            itemsData = response.products;
          } else {
            itemsData = [];
          }
          this.itemsRecords = itemsData || [];
          this.tableLoading = false;
        } else {
          this.itemsRecords = [];
          this.tableLoading = false;
        }
      } catch (error) {
        this.itemsRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    goBack() {
      this.$router.go(-1);
    }
  }
};
